  // Mail & Wellbeing · catalog + hub integrations
  'Helix Mail': 'بريد هيليكس',
  'Helix Wellbeing': 'هيليكس للرفاهية',
  'Nova Inbox — AI triage, screener, approvals & shared mailboxes': 'صندوق نوفا — فرز ذكي، فحص المرسلين، الموافقات وصناديق البريد المشتركة',
  'Nova Inbox: AI-ranked Priority stream, one-tap approvals from Expenses, Procurement & HR with live journey trackers, a first-contact Screener with phishing radar, snooze/schedule-send that respects Wellbeing quiet hours, shared mailboxes with collision detection, Drive attachments with DLP labels, EN ↔ AR drafting and 1-click hand-off to Projects, Calendar, CRM, Helpdesk & Pulse Chat.': 'صندوق نوفا: تدفق أولويات مرتب بالذكاء الاصطناعي، وموافقات بنقرة واحدة من المصروفات والمشتريات والموارد البشرية مع متتبعات رحلة مباشرة، وفاحص للمرسلين الجدد مع رادار للتصيد الاحتيالي، وتأجيل وجدولة إرسال تحترم ساعات الهدوء في تطبيق الرفاهية، وصناديق بريد مشتركة مع كشف التعارض، ومرفقات من Drive بتصنيفات منع تسرب البيانات، وصياغة بالإنجليزية والعربية، وتحويل بنقرة واحدة إلى المشاريع والتقويم وإدارة العملاء ومكتب المساعدة وPulse Chat.',
  'Aura — energy check-ins, breathwork, care & sustainable pace': 'أورا — تسجيلات الطاقة، تمارين التنفس، الرعاية ووتيرة عمل مستدامة',
  'Aura Wellbeing OS: a private living energy aura from 20-second check-ins, Nova recharge coaching tied to your Calendar meeting load and Focus Engine, guided breathwork & micro-resets, cross-hub movement challenges, confidential EAP counselling with a live care tracker, a burnout-radar Rhythm view with right-to-disconnect quiet hours honoured by Mail, and a wellbeing wallet of perks.': 'نظام أورا للرفاهية: هالة طاقة حية وخاصة من تسجيلات مدتها 20 ثانية، وتوجيه نوفا لاستعادة النشاط مرتبط بحِمل الاجتماعات في التقويم ومحرك التركيز، وتمارين تنفس موجهة واستراحات قصيرة، وتحديات حركة بين المكاتب، واستشارات سرية ضمن برنامج مساعدة الموظفين مع متتبع رعاية مباشر، وعرض الإيقاع برادار الاحتراق الوظيفي مع ساعات هدوء لحق الانفصال يحترمها البريد، ومحفظة مزايا للرفاهية.',
