  // Additional translations
  'Forge — code reviews, pipelines, deploys & DORA': 'فورج — مراجعات الكود، خطوط البناء، النشر ومؤشرات DORA',
  'Forge: a personal engineering cockpit with Nova AI code review and risk scoring, a live CI/CD pipeline tracker from commit to canary to production, one-click rollbacks honouring Incident Command deploy freezes, a service catalog with ownership scorecards, secret-scanning push protection backed by Vault, and DORA + review-equity insights that feed Performance evidence.': 'فورج: مقصورة هندسية شخصية مع مراجعة كود وتقييم مخاطر بالذكاء الاصطناعي من نوفا، ومتتبع مباشر لخطوط CI/CD من الإيداع إلى الإطلاق التدريجي فالإنتاج، وتراجع بنقرة واحدة يحترم تجميد النشر في قيادة الحوادث، ودليل خدمات ببطاقات كفاءة، وحماية دفع لفحص الأسرار مدعومة بالخزنة، وتحليلات DORA وعدالة المراجعة المتصلة بأدلة الأداء.',
  'My pull requests': 'طلبات الدمج الخاصة بي',
  'Deploy status': 'حالة النشر',
  'Pipeline runs': 'تشغيلات خطوط البناء',
  'Engineering metrics': 'مؤشرات الهندسة',
  'Stratos — infrastructure, SLOs, FinOps & GreenOps': 'ستراتوس — البنية السحابية، أهداف الخدمة، FinOps والاستدامة',
  'Stratos: a live multi-region infrastructure map (UAE, London, Singapore, Virginia), service health with SLOs and error budgets, policy-checked self-service provisioning with an approval tracker, observability with Nova root-cause hints correlated to DevHub deploys, and FinOps — budgets, anomalies, commitments, rightsizing and carbon per service.': 'ستراتوس: خريطة بنية تحتية مباشرة متعددة المناطق (الإمارات، لندن، سنغافورة، فرجينيا)، وصحة الخدمات مع أهداف SLO وميزانيات الأخطاء، وتزويد ذاتي خاضع للسياسات مع متتبع موافقات، ومراقبة أداء مع تلميحات نوفا للأسباب الجذرية المرتبطة بنشرات مركز المطورين، وإدارة مالية سحابية FinOps تشمل الميزانيات والشذوذ والالتزامات وتحسين الأحجام والبصمة الكربونية لكل خدمة.',
  'Service health': 'صحة الخدمات',
  'FinOps spend & budgets': 'إنفاق وميزانيات FinOps',
  'Provision a resource': 'تزويد مورد سحابي',
  'Observability & alerts': 'المراقبة والتنبيهات',
  'Sentinel — on-call, war rooms, status & postmortems': 'سينتينل — المناوبات، غرف الطوارئ، الحالة ومراجعات ما بعد الحادثة',
  'Sentinel: declare and run incidents with a live lifecycle tracker, a war room that auto-captures the timeline, pulls suspect deploys from DevHub and health from Cloud Console, freezes deploys, opens a HoloMeet bridge and posts updates to Pulse Chat, Mail and the hub status page; follow-the-sun on-call with fatigue signals for Wellbeing, alert noise reduction and Nova-drafted blameless postmortems.': 'سينتينل: إعلان وإدارة الحوادث عبر متتبع مراحل مباشر، وغرفة طوارئ توثّق الخط الزمني تلقائياً وتجلب النشرات المشتبه بها من مركز المطورين وصحة الخدمات من السحابة، وتجمّد النشر، وتفتح جسر هولوميت، وتنشر التحديثات إلى محادثات بالس والبريد وصفحة الحالة؛ مع جداول مناوبة عالمية ومؤشرات إجهاد متصلة بالرفاهية وتقليل ضجيج التنبيهات ومسودات مراجعة ما بعد الحادثة من نوفا.',
  'Declare an incident': 'إعلان حادثة',
  'Who\'s on call': 'من في المناوبة الآن',
  'Status page': 'صفحة الحالة',
  Postmortems: 'مراجعات ما بعد الحادثة',
  'Orbit — desks, rooms, visitors & workplace pulse': 'أوربت — المكاتب، القاعات، الزوار ونبض بيئة العمل',
  'Orbit Spaces: see who is in each office today, book desks on a live floor plan next to your team, find and book rooms with HoloMeet gear straight into Calendar, pre-register visitors with a badge-to-checkout tracker and host pings in Pulse Chat, raise facility requests, and give Workplace Ops live occupancy, air quality and utilisation insights across Dubai, London, Singapore and New York.': 'أوربت للمساحات: التعرّف على المتواجدين في كل مكتب اليوم، وحجز المكاتب على مخطط طابق تفاعلي بجوار فريقك، والبحث عن القاعات المجهزة بهولوميت وحجزها مباشرة في التقويم، والتسجيل المسبق للزوار مع متتبع من إصدار البطاقة حتى المغادرة وتنبيه المضيف في محادثات بالس، ورفع طلبات المرافق، وتزويد عمليات المكاتب بمؤشرات الإشغال وجودة الهواء والاستخدام في دبي ولندن وسنغافورة ونيويورك.',
  'Book a desk': 'حجز مكتب',
  'Register a visitor': 'تسجيل زائر',
  'Who\'s in today': 'المتواجدون اليوم',
  'Aegis — passwords, team vaults, secrets & JIT access': 'إيجيس — كلمات المرور، خزائن الفرق، الأسرار والوصول المؤقت',
  'Aegis Vault: a zero-knowledge personal vault and passkeys for everyone, team vaults with expiring one-time share links, engineering secrets with dynamic leases and rotation schedules wired to DevHub and Cloud Console, certificate lifecycle, just-in-time access with a live approval-to-lease tracker, break-glass and a tamper-evident audit trail feeding Security Center.': 'خزنة إيجيس: خزنة شخصية صفرية المعرفة ومفاتيح مرور للجميع، وخزائن فرق بروابط مشاركة مؤقتة لمرة واحدة، وأسرار هندسية بعقود وصول ديناميكية وجداول تدوير متصلة بمركز المطورين والسحابة، وإدارة دورة حياة الشهادات، ووصول مؤقت عند الطلب مع متتبع مباشر من الموافقة حتى انتهاء الصلاحية، ووصول طوارئ وسجل تدقيق غير قابل للتلاعب يغذي مركز الأمن.',
  'Open my vault': 'فتح خزنتي',
