  'Rotate expiring secrets': 'تدوير الأسرار قريبة الانتهاء',
  'Bastion — threats, posture, compliance & awareness': 'باستيون — التهديدات، الوضع الأمني، الامتثال والتوعية',
  'Bastion: everyone sees their personal security score (devices, passkeys, phishing readiness) and can report anything suspicious in one tap; the SOC gets a triage-to-recovery threat tracker with MITRE ATT&CK mapping, org posture stitched from Helpdesk devices, Cloud misconfigurations, DevHub vulnerabilities and Vault hygiene, auto-collected compliance evidence (ISO 27001, SOC 2, UAE IA, GDPR) and data-loss signals from Mail and Drive.': 'باستيون: يرى كل موظف درجته الأمنية الشخصية (الأجهزة، مفاتيح المرور، الجاهزية ضد التصيّد) مع الإبلاغ عن أي نشاط مشبوه بنقرة واحدة؛ ويحصل فريق العمليات الأمنية على متتبع تهديدات من الفرز حتى التعافي مربوط بإطار MITRE ATT&CK، ووضع أمني مؤسسي متكامل من أجهزة الدعم التقني وإعدادات السحابة وثغرات الكود ونظافة الخزنة، وأدلة امتثال آلية (ISO 27001 وSOC 2 وUAE IA وGDPR) وإشارات منع تسرب البيانات من البريد ودرايف.',
