  'Multi-region infrastructure, SLO error budgets, policy-guarded provisioning, observability and FinOps & Carbon.': 'بنية تحتية متعددة المناطق، وميزانيات أخطاء SLO، وتزويد محكوم بالسياسات، ومراقبة شاملة وإدارة مالية وكربونية.',
  'Production service health, p95 latency, 30-day error-budget burn rates and blast-radius dependency graph.': 'صحة خدمات الإنتاج، وزمن استجابة p95، ومعدلات استهلاك ميزانية الأخطاء لـ ٣٠ يوماً ومخطط الاعتمادية.',
  'Regional capacity quotas, Kubernetes nodepools, Aurora & Redis inventory, rightsizing and Terraform drift guard.': 'حصص السعة الإقليمية، ومجموعات عقد Kubernetes، وجرد Aurora وRedis، وتحسين الأحجام وحارس انحراف Terraform.',
  'Golden infrastructure templates with automated OPA security, UAE/EU residency and FinOps budget guardrails.': 'قوالب بنية تحتية قياسية مع ضوابط أمان OPA الآلية وإقامة بيانات الإمارات وأوروبا وحواجز ميزانية FinOps.',
