  'Late partition backfill': 'تعبئة متأخرة للأقسام',
  'Since warehouse-sync shipped 7 days ago, data-pipeline copies full partitions from eu-west-2 to the Snowflake account in us-east-1 every night. Inter-region transfer and NAT processing are billed per GB, so network spend went from about $179/day to $785/day.': 'منذ إطلاق مهمة warehouse-sync قبل ٧ أيام، تنسخ خدمة data-pipeline أقساماً كاملة من eu-west-2 إلى حساب Snowflake في us-east-1 كل ليلة. يتم احتساب النقل بين المناطق ومعالجة بوابة NAT لكل جيجابايت، مما رفع إنفاق الشبكة من ١٧٩$/يوم إلى ٧٨٥$/يوم.',
  'Switch warehouse-sync to incremental CDC exports and route it through the Snowflake PrivateLink endpoint in eu-west-2.': 'تحويل مهمة warehouse-sync إلى تصدير تزايدي CDC وتوجيهها عبر نقطة نهاية Snowflake PrivateLink في eu-west-2.',
  'payments-svc compute is up 38% since v2.41.0 reached production 40 minutes ago. Slow ledger queries hold connections longer, the HPA adds pods and client retries multiply traffic — classic retry-storm cost amplification.': 'ارتفعت حوسبة payments-svc بنسبة ٣٨٪ منذ وصول الإصدار v2.41.0 إلى الإنتاج قبل ٤٠ دقيقة. تحتفظ استعلامات دفتر الأستاذ البطيئة بالاتصالات لفترة أطول، مما يدفع التوسع التلقائي لإضافة حاويات وتضاعف محاولات إعادة الإرسال التكلفة.',
  'Roll back v2.41.0 (or add the missing ledger_entries index) and cap client retries with jittered backoff.': 'التراجع عن الإصدار v2.41.0 (أو إضافة فهرس ledger_entries المفقود) وتحديد محاولات إعادة الإرسال بتأخير تدريجي.',
  'A JupyterLab GPU notebook created by hand in ap-southeast-1 has been idle for three days with no auto-stop policy, billing about $29/day.': 'دفتر عمل JupyterLab GPU تم إنشاؤه يدوياً في منطقة ap-southeast-1 خامل منذ ٣ أيام دون سياسة إيقاف تلقائي بتكلفة ٢٩$/يوم.',
  'Stop the notebook and recreate it from the GPU notebook template (auto-stop after 8h).': 'إيقاف دفتر العمل وإعادة إنشائه من قالب دفاتر GPU القياسي (إيقاف تلقائي بعد ٨ ساعات).',
  'New warehouse-sync job copies full partitions eu-west-2 → us-east-1': 'مهمة warehouse-sync الجديدة تنسخ أقساماً كاملة من eu-west-2 إلى us-east-1',
  'Traffic leaves through the NAT gateway instead of PrivateLink': 'حركة البيانات تمر عبر بوابة NAT بدلاً من PrivateLink',
  '1.9 TB/day transferred vs 0.4 TB/day baseline': 'نقل ١.٩ تيرابايت/يوم مقابل خط الأساس ٠.٤ تيرابايت/يوم',
  'HPA scaled payments-svc from 12 to 19 pods after v2.41.0': 'توسع تلقائي لخدمة payments-svc من ١٢ إلى ١٩ حاوية بعد الإصدار v2.41.0',
  'Clients retry up to 3× on 5xx': 'إعادة محاولة العملاء حتى ٣ مرات عند أخطاء 5xx',
  'Correlated with p95 820ms in eu-west-2': 'مرتبط بزمن استجابة p95 البالغ 820ms في eu-west-2',
  'nb-embeddings-lab (g5.2xlarge) at 2% GPU for 3 days': 'دفتر nb-embeddings-lab (g5.2xlarge) يعمل بنسبة ٢٪ GPU منذ ٣ أيام',
